use semio_framework_value_paged_list::{PagedList,PagedListReleaseOutcome};
use semio_framework_value_control_contract::{RetainedCloneProgress,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[test]
fn original_plain_tail_keeps_items_backing_and_actual_work(){
 let f:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let(_,probe)=observe(||{let data=std::hint::black_box(Vec::<u8>::with_capacity(73));std::hint::black_box(data.as_ptr());drop(data)});assert_eq!(probe,(73,73));
 let(mut list,heap)=observe(||{let mut list=PagedList::<u8,64>::with_page_items(f["pageItems"].as_u64().unwrap()as usize);for value in f["input"].as_array().unwrap(){list.push(value.as_u64().unwrap()as u8)}list});assert_eq!(heap.1,0);
 let profile=serde_json::json!({"items":1024,"copyBytes":65536,"capacityBytes":65536,"releaseBytes":65536,"depth":64,"fuel":128});let mut wallet=Wallet::from_profile(&profile);let initial=wallet.loan(1,64);wallet.post(RetainedCloneProgress{retained_capacity_bytes:heap.0,..Default::default()},0,initial,heap);let mut bank=EffectBank::new(wallet);
 for(index,maximum)in f["maximumItems"].as_array().unwrap().iter().enumerate(){let g=bank.loan(maximum.as_u64().unwrap()as usize,64);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(list.discard_plain_tail(effect))));assert_eq!(marker,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("bounded plain tail cannot suspend")};assert_eq!(turn.work,1);assert_eq!(bank.take_admitted(),Some(true));let p=turn.result.unwrap();assert!(p.copied_items<=g.maximum_items);assert_eq!(heap,(0,0));bank.post(p,g,heap);assert_eq!(list.len(),f["remaining"][index].as_u64().unwrap()as usize)}
 let mut freed=0;while !list.terminal_is_empty(){let g=bank.loan(1,64);let((poll,marker),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(list.release_empty_page(effect))));assert_eq!(marker,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("plain tail backing release cannot suspend")};assert_eq!(bank.take_admitted(),Some(true));let PagedListReleaseOutcome::Ready(released)=turn.result.unwrap() else{panic!("funded release denied")};let p=RetainedCloneProgress{copied_items:usize::from(released.progressed),copied_bytes:released.placed_bytes,released_bytes:released.released_allocation_bytes,..Default::default()};freed+=p.released_bytes;bank.post(p,g,heap)}assert_eq!(freed,heap.0);assert_eq!(observe(||drop(list)).1,(0,0));
}
